using GSPTaskMiningAnalyzer.Models; namespace GSPTaskMiningAnalyzer; public sealed class StatisticsService { public AnalysisResult Analyze(IEnumerable<LogEvent> input,double maxGap=60){var events=input.OrderBy(e=>e.TimestampUtc).ToList(); var res=new AnalysisResult(); res.Events.AddRange(events); var d=new DurationCalculator{MaxGapSeconds=maxGap}.Calculate(events); res.From=events.FirstOrDefault()?.TimestampUtc; res.To=events.LastOrDefault()?.TimestampUtc; foreach(var (e,s) in d){ if(e.IsIdle||e.EventType is "idle_start") {res.IdleSeconds+=s; Add(res.IdleByDay,e.TimestampLocal.ToString("yyyy-MM-dd"),s);} else {res.ActiveSeconds+=s; Add(res.AppSeconds,string.IsNullOrEmpty(e.ProcessName)?"unknown":e.ProcessName,s); Add(res.ActiveByDay,e.TimestampLocal.ToString("yyyy-MM-dd"),s); Add(res.ActiveByHour,e.TimestampLocal.Hour,s);} if(e.EventType=="window_change") res.SwitchesByHour[e.TimestampLocal.Hour]=res.SwitchesByHour.GetValueOrDefault(e.TimestampLocal.Hour)+1;} for(int i=0;i<events.Count-1;i++){var a=events[i].ProcessName;var b=events[i+1].ProcessName;if(a!=b)res.Chains2[$"{a} → {b}"]=res.Chains2.GetValueOrDefault($"{a} → {b}")+1;} for(int i=0;i<events.Count-2;i++){var k=$"{events[i].ProcessName} → {events[i+1].ProcessName} → {events[i+2].ProcessName}";res.Chains3[k]=res.Chains3.GetValueOrDefault(k)+1;} BuildSessions(res,d); return res;} static void Add<TKey>(Dictionary<TKey,double> d,TKey k,double v) where TKey:notnull=>d[k]=d.GetValueOrDefault(k)+v; static void BuildSessions(AnalysisResult r,List<(LogEvent Event,double Seconds)> d){Session? cur=null; foreach(var (e,s) in d){ if(cur is null || cur.ProcessName!=e.ProcessName || cur.WindowTitle!=e.WindowTitle || cur.MachineName!=e.MachineName || cur.UserName!=e.UserName){ if(cur is not null) r.Sessions.Add(cur); cur=new(e.TimestampUtc,e.TimestampUtc.AddSeconds(s),s,e.ProcessName,e.WindowTitle,e.MachineName,e.UserName,string.IsNullOrEmpty(e.ScreenshotFile)?0:1);} else cur=cur with { End=e.TimestampUtc.AddSeconds(s), DurationSeconds=cur.DurationSeconds+s, ScreenshotCount=cur.ScreenshotCount+(string.IsNullOrEmpty(e.ScreenshotFile)?0:1)};} if(cur is not null) r.Sessions.Add(cur);} }
